import unittest,re
from tools.kjv_archive import load_register,read
class AmosFinalPlantingTests(unittest.TestCase):
 def test_withdrawn_threats_and_final_planting(self):
  prior,_=load_register('0.10-kjv.176');lang,manifest=load_register('0.10-kjv.177')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('amos-'):c for c in read(lang.folder/'amos-withdrawn-threats-and-final-planting-cases.json')};self.assertEqual(len(cases),60)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship','care'}&set(r['keys']))
  anchors={'6:1': ['woe', 'be:excl', 'chief of nation:pl'], '6:2': ['kjv_calneh', 'great kjv_hamath', 'kjv_gath', 'their/boundary more great'], '6:3': ['evil day far away', 'kjv_violence near'], '6:4': ['kjv_ivory lie:pr', 'kjv_calf:pl', 'kjv_cattle_stall'], '6:5': ['kjv_viol', 'instrument:pl of music invent:pr like kjv_david'], '6:6': ['wine in bowl:pl', 'chief kjv_ointment:pl', 'grief:caus:psv:neg:pr'], '6:7': ['one_num:ord', 'stretch:pa remove:psv:fu'], '6:8': ['by himself swear:perf', 'ipl kjv_excellence', 'all that in it'], '6:9': ['ten man:pl in one_num house', 'they die:fu'], '6:10': ['uncle of man', 'he that he:a burn:pr', 'say:fu no', 'wesg name of kjv_lord kjv_mention:inf:neg:may'], '6:11': ['great house with breach:pl', 'little house with split:ev:pl'], '6:12': ['upon rock', 'person there with ox:pl', 'kjv_gall_bitter', 'kjv_hemlock'], '6:13': ['wesg to wesg horn:pl', 'ourone/own strength', 'take:neg:perf?'], '6:14': ['kjv_hemath_place', 'river of kjv_wilderness'], '7:1': ['grasshopper:pl', 'later grow:ev', 'grass cut:ev:pl of king'], '7:2': ['forgive:imp i', 'by whom kjv_jacob rise:fu?', 'he small'], '7:3': ['kjv_relent:pa', 'it be:neg:fu'], '7:4': ['great deep devour:pa', 'part up eat:pa'], '7:5': ['cease:imp i', 'by whom kjv_jacob rise:fu?'], '7:6': ['kjv_relent:pa', 'this also be:neg:fu'], '7:7': ['wall by kjv_plumbline', 'kjv_plumbline in his/hand'], '7:8': ['i say:pa kjv_plumbline', 'ipl kjv_plumbline', 'mypl/people', 'again pass:neg:fu'], '7:9': ['kjv_isaac', 'house of kjv_jeroboam_joash'], '7:10': ['kjv_amaziah_bethel priest', 'conspire:perf', 'endure:neg:can'], '7:11': ['kjv_jeroboam_joash by sword die:fu', 'their/own land'], '7:12': ['kjv_seer', 'kjv_judah', 'bread eat:imp'], '7:13': ['kjv_sanctuary of king', 'court of king'], '7:14': ['i no prophet be:pa', 'i son of prophet be:pa', 'kjv_herdsman', 'kjv_sycomore'], '7:15': ['kjv_lord i:a take:pa as i flock', 'mypl/people'], '7:16': ['kjv_isaac drop:neg:imp'], '7:17': ['kjv_harlot', 'son:pl and thy/daughter:pl by sword', 'line kjv_divide:psv', 'kjv_pollute_sacred:psv:adj', 'forth of his/land'], '8:1': ['to i show:perf', 'kjv_basket of summer fruit'], '8:2': ['i say:pa kjv_basket', 'end upon mypl/people', 'again pass:neg:fu'], '8:3': ['song:pl of temple', 'howl:ev:pl', 'many kjv_corpse:pl', 'with silence'], '8:4': ['kjv_needy up kjv_swallow', 'poor of land fail:caus'], '8:5': ['new moon', 'wesg corn sell:may', 'kjv_ephah_measure small', 'kjv_shekel great', 'balance:pl by deceit false'], '8:6': ['wesg poor for silver', 'pair of shoe:pl', 'kjv_refuse_matter of wheat'], '8:7': ['by kjv_excellence of kjv_jacob', 'ipl any of their/work:pl never forget:fu'], '8:8': ['land for this tremble:neg:fu', 'every person', 'out cast:psv:fu and drown:psv:fu', 'flood of egypt'], '8:9': ['ipl sun at noon', 'earth in clear day'], '8:10': ['all kjv_loins', 'every head', 'only son', 'bitter day'], '8:11': ['not kjv_famine of bread nor thirst for water', 'hear:ev of word:pl'], '8:12': ['sea to sea', 'from kjv_north even to east', 'there and back', 'find:neg:fu'], '8:13': ['beautiful virgin:pl and young man:pl', 'for thirst faint:fu'], '8:14': ['sin of kjv_samaria', 'thy/god oh kjv_dan', 'manner of kjv_beersheba', 'never up rise:fu'], '9:1': ['i kjv_lord', 'kjv_lintel', 'kjv_structural_post:pl', 'ipl last of they', 'deliver:psv:neg:fu'], '9:2': ['kjv_hell_depth kjv_dig', 'mypl/hand', 'up to heaven climb'], '9:3': ['top of kjv_carmel', 'bottom of sea', 'serpent command:fu'], '9:4': ['kjv_captivity before their/enemy:pl', 'ipl sword command:fu', 'for evil set:fu and not for good'], '9:5': ['land touch:pr', 'it melt:fu', 'flood of egypt'], '9:6': ['his/kjv_storey:pl', 'his/troop', 'kjv_foundation set:perf', 'water:pl of sea'], '9:7': ['child:pl of kjv_ethiopia to ipl', 'egypt', 'kjv_caphtor', 'kjv_syria from kjv_kir'], '9:8': ['sinful kingdom', 'destroy:fu except', 'kjv_jacob entirely destroy:neg:fu'], '9:9': ['among all nation:pl', 'kjv_dry_sieve', 'least seed upon earth fall:neg:fu'], '9:10': ['sin:ag:pl of mypl/people', 'evil wesg:a overtake:neg:fu', 'nor before wesg:a come:fu'], '9:11': ['kjv_tabernacle of kjv_david', 'breach:pl of it', 'his/ruin:pl', 'day:pl of old'], '9:12': ['remainder of kjv_edom', 'all kjv_heathen', 'by mypl/name call:psv:pr'], '9:13': ['plough:ag reap:ag overtake', 'tread:ag of grape:pl', 'sweet wine drop', 'hill:pl melt'], '9:14': ['kjv_captivity of mypl/people', 'kjv_desolate city:pl', 'kjv_vineyard:pl', 'kjv_garden:pl'], '9:15': ['they no more', 'which ipl they:a give:perf', 'kjv_lord thy/god']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('wesg corn sell:may',cases['8-5']['analysis'])
  self.assertIn('for evil set:fu and not for good',cases['9-4']['analysis'])
  self.assertIn('before wesg:a come:fu',cases['9-10']['analysis'])
  self.assertFalse(any(':du' in c['analysis'] for c in cases.values()))
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),3)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
